import {WEAPONS} from '../../src/data.js';import {stageById} from '../../src/campaign.js';import {villageStats} from '../../src/village-stats.js';
export const RUN_KEY='wandering-hearth:run';
const finite=(v,min=0,max=1e9)=>Number.isFinite(v)&&v>=min&&v<=max;
const position=v=>Array.isArray(v)&&v.length===3&&v.every(n=>finite(n,-100,100));
// The 0.1 writer saved expired timers as negatives; readiness is now zero.
export function normalizeCheckpoint(c,save){const r=c?.run;if(c?.version!==1||!r||typeof r.id!=='string'||!r.id||save.settledRuns.includes(r.id)||r.outcome||![1,2,3].includes(r.stage)||!finite(r.hp,.001,10000)||!finite(r.maxHp,r.hp,10000)||!(finite(r.time,0,1e7)&&r.time<1e7)||!position(c.position)||!finite(c.rotation,-1e8,1e8)||!r.weapons||Array.isArray(r.weapons)||Object.keys(r.weapons).length<1||Object.keys(r.weapons).length>8||Object.entries(r.weapons).some(([k,v])=>!WEAPONS[k]||!Number.isInteger(v)||v<1||v>5)||!Array.isArray(c.enemies)||c.enemies.length>40)return null;const stage=stageById(r.stageId),run={...r,stageId:stage.id,duration:stage.duration};for(const key of ['coins','kills','level','xp'])if(!finite(run[key],key==='level'?1:0,key==='level'?200:1e7))return null;for(const key of ['boostCd','boostTime','shieldCd','shieldTime','repairCd','invuln','slowTime'])run[key]=finite(run[key],0,120)?run[key]:0;run.cooldowns=Object.fromEntries(Object.entries(r.cooldowns??{}).filter(([k,v])=>WEAPONS[k]&&finite(v,-10,120)));const baseline=villageStats(save);run.villageStats=Object.keys(baseline).every(k=>finite(r.villageStats?.[k],0,10000))?r.villageStats:baseline;run.choices=(Array.isArray(r.choices)?r.choices:[]).filter(x=>x&&['grow','heal','engine','armor','weapon'].includes(x.type)&&(x.type!=='weapon'||WEAPONS[x.key]&&Number.isInteger(x.level)&&x.level>=1&&x.level<=5)).slice(0,3);const enemies=c.enemies.filter(e=>e&&['cannon','pursuer','charger','elite','boss'].includes(e.kind)&&finite(e.hp,.001)&&finite(e.maxHp,e.hp)&&finite(e.attack,-1e7,1000)&&position(e.position));if(enemies.length!==c.enemies.length)return null;return {...c,run,screen:c.screen==='upgrade'&&run.choices.length?'upgrade':'',enemies:enemies.map(e=>e.attack<0?{...e,attack:0}:e),loot:(Array.isArray(c.loot)?c.loot:[]).filter(l=>position(l.position)&&finite(l.value,0,1e7)&&(!l.gold||finite(l.gold,0,1e7))).slice(0,300)};}
export function loadCheckpoint(save,storage=globalThis.localStorage){for(const key of [RUN_KEY,RUN_KEY+':backup'])try{const c=normalizeCheckpoint(JSON.parse(storage.getItem(key)),save);if(c)return c;}catch{}return null;}
export function saveCheckpoint(c,save,storage=globalThis.localStorage){const clean=normalizeCheckpoint(c,save);if(!clean)return false;try{const old=storage.getItem(RUN_KEY);if(old)try{if(normalizeCheckpoint(JSON.parse(old),save))storage.setItem(RUN_KEY+':backup',old);}catch{}storage.setItem(RUN_KEY,JSON.stringify(clean));return true;}catch{return false;}}
export function clearCheckpoint(storage=globalThis.localStorage){for(const key of [RUN_KEY,RUN_KEY+':backup'])try{storage.removeItem(key);}catch{}}
